sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float shadowLength;
uniform float angle;
layout(color) uniform half4 shadowColor;
uniform float fade;
uniform float shadowOpacity;
uniform float hardness;
uniform float opacity;
float4 texT(float2 p) {
    return float4(image.eval(p));
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
half4 main(float2 coord) {
    float4 c = texT(coord);
    float2 dir = float2(cos(radians(angle)), sin(radians(angle)));
    float sa = 0.0;
    for (int i = 0; i < 32; i++) {
        float t = float(i) / 31.0;
        sa = max(sa, texT(coord - dir * shadowLength * t).a * (1.0 - fade * t));
    }
    sa = mix(sa, step(0.5, sa), hardness) * shadowOpacity;
    float4 shadow = float4(float3(shadowColor.rgb) * sa, sa);
    return fin(c, c + shadow * (1.0 - c.a), opacity);
}
